// Block (composition) — a notification trigger opening a rich notification popover.
// Popover owns overlay behavior; NotificationList owns the notification composition.
import { Badge } from "../components/Badge";
import { Text } from "react-aria-components";
import { Button } from "../components/Button";
import { PopoverContent, PopoverTrigger } from "../components/Popover";
import { NotificationList } from "./NotificationList";
import "./NotificationMenu.css";

export interface NotificationMenuProps {
  items: { id: string; title: string; description?: string }[];
  unreadCount?: number;
  triggerLabel?: string;
  className?: string;
}

export function NotificationMenu({
  items,
  unreadCount = 0,
  triggerLabel = "Notifications",
  className,
}: NotificationMenuProps) {
  return (
    <PopoverTrigger>
      <Button
        variant="secondary"
        size="small"
        aria-label={triggerLabel}
        className={className ? `sd-notificationmenu ${className}` : "sd-notificationmenu"}
      >
        {/* A word and its Badge are Button's own content row (button.gap, and <Text> takes
            the text padding), so the Block adds no gap of its own. */}
        <Text>{triggerLabel}</Text>
        {unreadCount > 0 && <Badge variant="tonal">{unreadCount}</Badge>}
      </Button>
      <PopoverContent placement="bottom end" className="sd-notificationmenu__content">
        <NotificationList items={items} />
      </PopoverContent>
    </PopoverTrigger>
  );
}

/* NotificationMenu.css — .sd-notificationmenu (Block)
   Arrangement only: sizes the rich notification panel for narrow and wide viewports. */
.sd-notificationmenu {
  flex-shrink: 0;
}

.sd-notificationmenu__content {
  width: min(24rem, 90vw);
}
